/// A position in the TOML source text.
pub(all) struct Position {
  line : Int
  col : Int
} derive(Eq, Debug, ToJson)

///|
pub fn Position::to_string(self : Position) -> String {
  "\{self.line}:\{self.col}"
}

///|
/// Error type for TOML parsing errors.
pub(all) suberror ParseError {
  /// A syntax error at a given position.
  SyntaxError(pos~ : Position, msg : String)
  /// A duplicate key at a given position.
  DuplicateKey(pos~ : Position, key : String) // the duplicate key
} derive(Eq, Debug, ToJson)

///|
pub fn ParseError::to_string(self : ParseError) -> String {
  match self {
    SyntaxError(pos~, msg~) => "syntax error at \{pos.to_string()}: \{msg}"
    DuplicateKey(pos~, key~) => "duplicate key at \{pos.to_string()}: \"\{key}\""
  }
}
