/// Internal parser state
struct ParserState {
  input : String
  mut pos : Int
  mut line : Int
  mut col : Int
}

///|
fn ParserState::new(input : String) -> ParserState {
  { input, pos: 0, line: 1, col: 1 }
}

///|
fn ParserState::peek(self : ParserState) -> Char? {
  if self.pos >= self.input.length() {
    None
  } else {
    self.input.get_char(self.pos)
  }
}

///|
fn ParserState::advance(self : ParserState) -> Unit {
  if self.pos < self.input.length() {
    let c : UInt16 = self.input[self.pos]
    if c == '\n' {
      self.line += 1
      self.col = 1
    } else {
      self.col += 1
    }
    self.pos += 1
  }
}

///|
fn ParserState::curr_pos(self : ParserState) -> Position {
  { line: self.line, col: self.col }
}

///|
/// Skip whitespace (spaces and tabs, not newlines) and comments.
fn ParserState::skip_whitespace(self : ParserState) -> Unit {
  loop {
    let c = self.peek()
    if c is Some(' ' | '\t') {
      self.advance()
    } else if c is Some('#') {
      self.skip_comment()
    } else {
      break
    }
  }
}

///|
/// Skip whitespace and newlines, and comments.
fn ParserState::skip_whitespace_and_newlines(self : ParserState) -> Unit {
  loop {
    let c = self.peek()
    if c is Some(' ' | '\t' | '\n') {
      self.advance()
    } else if c is Some('#') {
      self.skip_comment()
    } else {
      break
    }
  }
}

///|
/// Skip from '#' to end of line.
fn ParserState::skip_comment(self : ParserState) -> Unit {
  loop {
    let c = self.peek()
    if c is None || c is Some('\n') {
      break
    }
    self.advance()
  }
}

///|
/// Parse a bare key (alphanumeric, underscore, hyphen).
fn ParserState::parse_bare_key(self : ParserState) -> String? {
  let start = self.pos
  let start_col = self.col
  let mut ok = false
  loop {
    let c = self.peek()
    if c is Some('a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-') {
      self.advance()
      ok = true
    } else {
      break
    }
  }
  if !ok {
    return None
  }
  Some(self.input[start:self.pos].to_string())
}

///|
/// Parse a dotted key into an array of key parts.
fn ParserState::parse_key(self : ParserState) -> Array[String] raise ParseError {
  let parts : Array[String] = []
  loop {
    self.skip_whitespace()
    let part = self.parse_bare_key()
    if part is None {
      raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected a key")
    }
    let p : String = part
    parts.push(p)
    self.skip_whitespace()
    if self.peek() is Some('.') {
      self.advance()
    } else {
      break
    }
  }
  if parts.is_empty() {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected a key")
  }
  parts
}

///|
/// Parse a quoted string value.
fn ParserState::parse_string(self : ParserState) -> String raise ParseError {
  let c = self.peek()
  guard c is Some('"') else {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected '\"'")
  }
  self.advance() // consume opening quote
  let buf = StringBuilder()
  loop {
    let c2 = self.peek()
    match c2 {
      None => {
        raise SyntaxError(
          pos~ : self.curr_pos(),
          msg~ : "unterminated string",
        )
      }
      Some('"') => {
        self.advance() // consume closing quote
        break
      }
      Some('\\') => {
        self.advance() // consume backslash
        let esc = self.peek()
        match esc {
          None => raise SyntaxError(
            pos~ : self.curr_pos(),
            msg~ : "unterminated escape sequence",
          )
          Some('"') => {
            self.advance()
            buf.write_char('"')
          }
          Some('\\') => {
            self.advance()
            buf.write_char('\\')
          }
          Some('n') => {
            self.advance()
            buf.write_char('\n')
          }
          Some('t') => {
            self.advance()
            buf.write_char('\t')
          }
          Some(c3) => {
            raise SyntaxError(
              pos~ : self.curr_pos(),
              msg~ : "invalid escape sequence: '\\\{c3}'",
            )
          }
        }
      }
      Some(c4) => {
        self.advance()
        buf.write_char(c4)
      }
    }
  }
  buf.to_string()
}

///|
/// Parse an integer value.
fn ParserState::parse_integer(self : ParserState) -> Int64 raise ParseError {
  let start = self.pos
  // optional sign
  if self.peek() is Some('+' | '-') {
    self.advance()
  }
  // digits (at least one required)
  let mut has_digit = false
  loop {
    let c = self.peek()
    if c is Some('0'..='9') {
      self.advance()
      has_digit = true
    } else {
      break
    }
  }
  if !has_digit {
    raise SyntaxError(
      pos~ : self.curr_pos(),
      msg~ : "expected integer digits",
    )
  }
  let s = self.input[start:self.pos]
  match @strconv.from_str(s) {
    Ok(n) => n
    Err(_) => raise SyntaxError(
      pos~ : self.curr_pos(),
      msg~ : "invalid integer: \"\{s.to_string()}\"",
    )
  }
}

///|
/// Parse a boolean value.
fn ParserState::parse_bool(self : ParserState) -> Bool raise ParseError {
  let start = self.pos
  // try match "true"
  if self.pos + 4 <= self.input.length() {
    if self.input[self.pos:self.pos + 4] == "true" {
      let after = if self.pos + 4 < self.input.length() {
        self.input.get_char(self.pos + 4)
      } else {
        None
      }
      if after is None || !(after is Some('a'..='z' | 'A'..='Z' | '0'..='9' | '_')) {
        for _i in 0..<4 {
          self.advance()
        }
        return true
      }
    }
  }
  // try match "false"
  if self.pos + 5 <= self.input.length() {
    if self.input[self.pos:self.pos + 5] == "false" {
      let after = if self.pos + 5 < self.input.length() {
        self.input.get_char(self.pos + 5)
      } else {
        None
      }
      if after is None || !(after is Some('a'..='z' | 'A'..='Z' | '0'..='9' | '_')) {
        for _i in 0..<5 {
          self.advance()
        }
        return false
      }
    }
  }
  raise SyntaxError(
    pos~ : self.curr_pos(),
    msg~ : "expected boolean (true/false)",
  )
}

///|
/// Parse an array value.
fn ParserState::parse_array(self : ParserState) -> Json raise ParseError {
  guard self.peek() is Some('[') else {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected '['")
  }
  self.advance() // consume '['
  let items : Array[Json] = []
  loop {
    self.skip_whitespace_and_newlines()
    if self.peek() is Some(']') {
      self.advance()
      break
    }
    if !items.is_empty() {
      self.skip_whitespace_and_newlines()
      guard self.peek() is Some(',') else {
        raise SyntaxError(
          pos~ : self.curr_pos(),
          msg~ : "expected ',' or ']' in array",
        )
      }
      self.advance()
      self.skip_whitespace_and_newlines()
    }
    let val = self.parse_value()
    items.push(val)
  }
  Json::array(items)
}

///|
/// Parse a value.
fn ParserState::parse_value(self : ParserState) -> Json raise ParseError {
  self.skip_whitespace()
  let c = self.peek()
  match c {
    Some('"') => Json::string(self.parse_string())
    Some('t' | 'f') => Json::boolean(self.parse_bool())
    Some('[') => self.parse_array()
    Some('+' | '-' | '0'..='9') => {
      let n = self.parse_integer()
      Json::number(n.to_double(), repr=Some(n.to_string()))
    }
    _ => {
      raise SyntaxError(
        pos~ : self.curr_pos(),
        msg~ : "expected value (string, integer, boolean, or array)",
      )
    }
  }
}

///|
/// Parse a table header like [key] or [key.subkey].
fn ParserState::parse_table_header(self : ParserState) -> Array[String] raise
  ParseError {
  self.skip_whitespace()
  guard self.peek() is Some('[') else {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected '['")
  }
  self.advance()
  let parts = self.parse_key()
  self.skip_whitespace()
  guard self.peek() is Some(']') else {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected ']'")
  }
  self.advance()
  parts
}

///|
/// A parsed entry: table path, key parts, and value.
struct Entry {
  table_path : Array[String]
  key_parts : Array[String]
  value : Json
}

///|
