          st.advance()
        } else if after is Some(_) {
          raise SyntaxError(
            pos~ : st.curr_pos(),
            msg~ : "expected newline after table header",
          )
        }
      }
      Some('\n') => {
        st.advance()
      }
      Some('#') => {
        st.skip_comment()
        // after comment, expect newline or end
        if st.peek() is Some('\n') {
          st.advance()
        }
      }
      _ => {
        // key-value pair
        let key_parts = st.parse_key()
        st.skip_whitespace()
        guard st.peek() is Some('=') else {
          raise SyntaxError(
            pos~ : st.curr_pos(),
            msg~ : "expected '='",
          )
        }
        st.advance() // consume '='
        let val = st.parse_value()
        // after value, expect newline, comment, or end
        st.skip_whitespace()
        let after = st.peek()
        if after is Some('#') {
          st.skip_comment()
          if st.peek() is Some('\n') {
            st.advance()
          } else if st.peek() is Some(_) {
            raise SyntaxError(
              pos~ : st.curr_pos(),
              msg~ : "expected newline after value",
            )
          }
        } else if after is Some('\n') {
          st.advance()
        } else if after is Some(_) {
