/// Internal parser state
struct ParserState {
  input : String
  mut pos : Int
  mut line : Int
  mut col : Int
}

///|
fn ParserState::new(input : String) -> ParserState {
  { input, pos: 0, line: 1, col: 1 }
}

///|
fn ParserState::peek(self : ParserState) -> Char? {
  if self.pos >= self.input.length() {
    None
  } else {
    self.input.get_char(self.pos)
  }
}

///|
fn ParserState::advance(self : ParserState) -> Unit {
  if self.pos < self.input.length() {
    let c : UInt16 = self.input[self.pos]
    if c == '\n' {
      self.line += 1
      self.col = 1
    } else {
      self.col += 1
    }
    self.pos += 1
  }
}

///|
fn ParserState::curr_pos(self : ParserState) -> Position {
  { line: self.line, col: self.col }
}

///|
fn ParserState::skip_whitespace(self : ParserState) -> Unit {
  loop {
    let c = self.peek()
    if c is Some(' ' | '\t') {
      self.advance()
    } else if c is Some('#') {
      self.skip_comment()
    } else {
      break
    }
  }
}

///|
fn ParserState::skip_whitespace_and_newlines(self : ParserState) -> Unit {
  loop {
    let c = self.peek()
    if c is Some(' ' | '\t' | '\n') {
      self.advance()
    } else if c is Some('#') {
      self.skip_comment()
    } else {
      break
    }
  }
}

///|
fn ParserState::skip_comment(self : ParserState) -> Unit {
  loop {
    let c = self.peek()
    if c is None || c is Some('\n') {
      break
    }
    self.advance()
  }
}

///|
fn ParserState::expect_newline_or_eof(self : ParserState) -> Unit raise ParseError {
  self.skip_whitespace()
  let c = self.peek()
  match c {
    None => ()
    Some('#') => {
      self.skip_comment()
      // after comment, expect newline or eof
      match self.peek() {
        None => ()
        Some('\n') => self.advance()
        Some(other) => raise SyntaxError(
          pos~ : self.curr_pos(),
          msg~ : "expected newline after comment, got '\{other.to_string()}'",
        )
      }
    }
    Some('\n') => self.advance()
    Some(other) => raise SyntaxError(
      pos~ : self.curr_pos(),
      msg~ : "expected newline, got '\{other.to_string()}'",
    )
  }
}

///|
/// Parse a bare key.
fn ParserState::parse_bare_key(self : ParserState) -> String? {
  let start = self.pos
  let mut ok = false
  loop {
    let c = self.peek()
    if c is Some('a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-') {
      self.advance()
      ok = true
    } else {
      break
    }
  }
  if !ok {
    return None
  }
  Some(self.input[start:self.pos].to_string())
}

///|
/// Parse a dotted key into an array of key parts.
fn ParserState::parse_key(self : ParserState) -> Array[String] raise ParseError {
  let parts : Array[String] = []
  loop {
    self.skip_whitespace()
    let part = self.parse_bare_key()
    if part is None {
      if parts.is_empty() {
        raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected a key")
      }
      raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected a key after '.'")
    }
    parts.push(part)
    self.skip_whitespace()
    if self.peek() is Some('.') {
      self.advance()
    } else {
      break
    }
  }
  parts
}

///|
/// Parse a quoted string value.
fn ParserState::parse_string(self : ParserState) -> String raise ParseError {
  guard self.peek() is Some('"') else {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected '\"'")
  }
  self.advance()
  let buf = StringBuilder()
  loop {
    let c = self.peek()
    match c {
      None => raise SyntaxError(pos~ : self.curr_pos(), msg~ : "unterminated string")
      Some('"') => {
        self.advance()
        break
      }
      Some('\\') => {
        self.advance()
        let esc = self.peek()
        match esc {
          None => raise SyntaxError(
            pos~ : self.curr_pos(),
            msg~ : "unterminated escape sequence",
          )
          Some('"') => { self.advance(); buf.write_char('"') }
          Some('\\') => { self.advance(); buf.write_char('\\') }
          Some('n') => { self.advance(); buf.write_char('\n') }
          Some('t') => { self.advance(); buf.write_char('\t') }
          Some(c3) => raise SyntaxError(
            pos~ : self.curr_pos(),
            msg~ : "invalid escape sequence '\\\{c3}'",
          )
        }
      }
      Some(c4) => {
        self.advance()
        buf.write_char(c4)
      }
    }
  }
  buf.to_string()
}

///|
/// Parse an integer value.
fn ParserState::parse_integer(self : ParserState) -> Int64 raise ParseError {
  let start = self.pos
  if self.peek() is Some('+' | '-') {
    self.advance()
  }
  let mut has_digit = false
  loop {
    let c = self.peek()
    if c is Some('0'..='9') {
      self.advance()
      has_digit = true
    } else {
      break
    }
  }
  if !has_digit {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected integer digit")
  }
  let s = self.input[start:self.pos]
  match @strconv.from_str(s) {
    Ok(n) => n
    Err(_) => raise SyntaxError(
      pos~ : self.curr_pos(),
      msg~ : "invalid integer \"\{s.to_string()}\"",
    )
  }
}

///|
/// Parse a boolean value.
fn ParserState::parse_bool(self : ParserState) -> Bool raise ParseError {
  let start = self.pos
  // Try "true"
  if self.pos + 4 <= self.input.length() &&
    self.input[self.pos:self.pos + 4] == "true" {
    let after = if self.pos + 4 < self.input.length() {
      self.input.get_char(self.pos + 4)
    } else {
      None
    }
    if after is None || !(after is Some('a'..='z' | 'A'..='Z' | '0'..='9' | '_')) {
      for _i in 0..<4 { self.advance() }
      return true
    }
  }
  // Try "false"
  if self.pos + 5 <= self.input.length() &&
    self.input[self.pos:self.pos + 5] == "false" {
    let after = if self.pos + 5 < self.input.length() {
      self.input.get_char(self.pos + 5)
    } else {
      None
    }
    if after is None || !(after is Some('a'..='z' | 'A'..='Z' | '0'..='9' | '_')) {
      for _i in 0..<5 { self.advance() }
      return false
    }
  }
  raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected boolean (true/false)")
}

///|
/// Parse an array value.
fn ParserState::parse_array(self : ParserState) -> Json raise ParseError {
  guard self.peek() is Some('[') else {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected '['")
  }
  self.advance()
  let items : Array[Json] = []
  loop {
    self.skip_whitespace_and_newlines()
    match self.peek() {
      Some(']') => {
        self.advance()
        break
      }
      _ => ()
    }
    if !items.is_empty() {
      self.skip_whitespace_and_newlines()
      guard self.peek() is Some(',') else {
        raise SyntaxError(
          pos~ : self.curr_pos(),
          msg~ : "expected ',' or ']' in array",
        )
      }
      self.advance()
      self.skip_whitespace_and_newlines()
    }
    let val = self.parse_value()
    items.push(val)
  }
  Json::array(items)
}

///|
/// Parse a value: string, integer, boolean, or array.
fn ParserState::parse_value(self : ParserState) -> Json raise ParseError {
  self.skip_whitespace()
  let c = self.peek()
  match c {
    Some('"') => Json::string(self.parse_string())
    Some('t' | 'f') => Json::boolean(self.parse_bool())
    Some('[') => self.parse_array()
    Some('+' | '-' | '0'..='9') => {
      let n = self.parse_integer()
      Json::number(n.to_double(), repr=Some(n.to_string()))
    }
    _ => raise SyntaxError(
      pos~ : self.curr_pos(),
      msg~ : "expected value (string, integer, boolean, or array)",
    )
  }
}

///|
/// Parse a table header like [key] or [key.subkey].
fn ParserState::parse_table_header(self : ParserState) -> Array[String] raise
  ParseError {
  guard self.peek() is Some('[') else {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected '['")
  }
  self.advance()
  let parts = self.parse_key()
  self.skip_whitespace()
  guard self.peek() is Some(']') else {
    raise SyntaxError(pos~ : self.curr_pos(), msg~ : "expected ']'")
  }
  self.advance()
  parts
}

///|
/// A parsed entry with positional info for error reporting.
struct Entry {
  table_path : Array[String]
  key_parts : Array[String]
  value : Json
  table_line : Int
  table_col : Int
  key_line : Int
  key_col : Int
}

///|
/// Parse TOML input into a list of entries.
fn parse_entries(input : String) -> Array[Entry] raise ParseError {
  let st = ParserState::new(input)
  let entries : Array[Entry] = []
  let mut current_path : Array[String] = []
  let mut table_line = 1
  let mut table_col = 1

  loop {
    st.skip_whitespace_and_newlines()
    let c = st.peek()
    match c {
      None => break
      Some('[') => {
        let pos = st.curr_pos()
        current_path = st.parse_table_header()
        table_line = pos.line
        table_col = pos.col
        st.expect_newline_or_eof()
      }
      Some('#') => {
        st.skip_comment()
        st.expect_newline_or_eof()
      }
      Some('\n') => {
        st.advance()
      }
      _ => {
        let key_pos = st.curr_pos()
        let key_parts = st.parse_key()
        st.skip_whitespace()
        guard st.peek() is Some('=') else {
          raise SyntaxError(pos~ : st.curr_pos(), msg~ : "expected '='")
        }
        st.advance()
        let val = st.parse_value()
        st.expect_newline_or_eof()
        entries.push({
          table_path: current_path,
          key_parts,
          value: val,
          table_line,
          table_col,
          key_line: key_pos.line,
          key_col: key_pos.col,
        })
      }
    }
  }
  entries
}

///|
/// Build a nested Json object from parsed entries, checking for duplicates.
fn build_json(entries : Array[Entry]) -> Json raise ParseError {
  // We'll build a tree bottom-up.
  // Strategy: group entries by their table path, then recursively nest.

  // First, group entries by table path.
  // Map from table_path_string to Array[Entry]
  let table_groups : Map[String, Array[Entry]] = {}

  for entry in entries {
    let tkey = entry.table_path.join(".")
    if !table_groups.contains(tkey) {
      table_groups[tkey] = []
    }
    table_groups[tkey].push(entry)
  }

  // For each group, build the table-level map, checking for duplicate keys.
  // Then nest them according to table path hierarchy.

  // Build table_map: table_path_string -> Map[String, Json]
  let table_maps : Map[String, Map[String, Json]] = {}

  for tkey, group in table_groups {
    let tmap : Map[String, Json] = {}
    for entry in group {
      let full_key = entry.key_parts.join(".")
      if tmap.contains(full_key) {
        raise DuplicateKey(
          pos~ : { line: entry.key_line, col: entry.key_col },
          key~ : full_key,
        )
      }
      // For dotted keys like "a.b", we need to build nested maps within the table.
      // Let me handle this with a nested insertion.
      insert_nested(tmap, entry.key_parts, 0, entry.value)
    }
    table_maps[tkey] = tmap
  }

  // Now build the final tree by nesting table_maps.
  // Determine the hierarchy of table paths.
  // For each table path, find its parent and nest.

  // Sort table paths by length for bottom-up building.
  let sorted_paths : Array[String] = []
  for tkey, _ in table_maps {
    sorted_paths.push(tkey)
  }
  // Sort by number of parts (fewer = parent)
  sorted_paths.sort_by(fn(a, b) {
    let da = a.split(".").length()
    let db = b.split(".").length()
    da - db
  })

  // Now nest: for each path (except root ""), find its parent and nest it.
  let root_map : Map[String, Json] = {}

  // Handle root entries (empty table path)
  if table_maps.contains("") {
    for k, v in table_maps[""] {
      root_map[k] = v
    }
  }

  // For non-root table paths, nest them.
  // First, identify which paths are top-level tables vs nested.
  // E.g., ["db", "settings"] means the table [db.settings] is nested under [db].

  // Better approach: collect all qualified keys (table_path + key_parts) and build from that.
  // Let me restart: build a single flat key -> value map, then convert to nested JSON.

  // Actually simplest approach:
  // 1. For each entry, create fully-qualified dotted key
  // 2. Check for duplicates
  // 3. Build nested Json from the flat structure

  // Let me redo this more cleanly.

  // Flat key -> value
  let flat : Map[String, Json] = {}
  for entry in entries {
    let parts : Array[String] = []
    for p in entry.table_path {
      parts.push(p)
    }
    for p in entry.key_parts {
      parts.push(p)
    }
    let fqkey = parts.join(".")
    if flat.contains(fqkey) {
      raise DuplicateKey(
        pos~ : { line: entry.key_line, col: entry.key_col },
        key~ : fqkey,
      )
    }
    flat[fqkey] = entry.value
  }

  // Now convert flat map to nested JSON tree.
  let root : Map[String, Json] = {}
  for fqkey, val in flat {
    let parts = fqkey.split(".")
    insert_nested_json(root, parts, 0, val)
  }
  Json::object(root)
}

///|
/// Insert a value into a nested map structure following key parts.
fn insert_nested(
  parent : Map[String, Json],
  parts : Array[String],
  idx : Int,
  value : Json,
) -> Unit {
  let part = parts[idx]
  if idx == parts.length() - 1 {
    if parent.contains(part) {
      // Duplicate - but this should have been caught earlier
      parent[part] = value
    } else {
      parent[part] = value
    }
  } else {
    // Navigate or create intermediate map
    if !parent.contains(part) {
      parent[part] = Json::object({})
    }
    let sub = parent[part]
    match sub {
      Object(submap) => {
        insert_nested(submap, parts, idx + 1, value)
      }
      _ => {
        // Value exists but is not a table - error (shouldn't happen with valid TOML)
        parent[part] = Json::object({})
        let sub2 = parent[part]
        match sub2 {
          Object(submap) => {
            insert_nested(submap, parts, idx + 1, value)
          }
          _ => ()
        }
      }
    }
  }
}

///|
/// Insert a value following key parts into a mutable map, creating nested objects as needed.
fn insert_nested_json(
  parent : Map[String, Json],
  parts : Array[String],
  idx : Int,
  value : Json,
) -> Unit {
  let part = parts[idx]
  if idx == parts.length() - 1 {
    parent[part] = value
  } else {
    if !parent.contains(part) {
      parent[part] = Json::object({})
    }
    let sub = parent[part]
    match sub {
      Object(submap) => {
        insert_nested_json(submap, parts, idx + 1, value)
      }
      _ => {
        // Overwrite with new object
        parent[part] = Json::object({})
        let sub2 = parent[part]
        match sub2 {
          Object(submap) => {
            insert_nested_json(submap, parts, idx + 1, value)
          }
          _ => ()
        }
      }
    }
  }
}
"}

