/// Parse TOML `input` text into a `Json` value.
///
/// # Example
/// ```mbt check
/// test {
///   let toml = "name = \"hello\"\ncount = 42"
///   let json = @tomlparse.parse_toml(toml)
///   let output = json.stringify()
///   inspect(output, content="{\"count\":42,\"name\":\"hello\"}")
/// }
/// ```
///
/// # Errors
/// Raises `ParseError` on invalid TOML input or duplicate keys.
pub fn parse_toml(input : String) -> Json raise ParseError {
  let entries = parse_entries(input)
  build_json(entries)
}
"}

