/// Internal parser state
struct ParserState {
  input : String
  mut pos : Int
  mut line : Int
  mut col : Int
}

///|
fn ParserState::new(input : String) -> ParserState {
  { input, pos: 0, line: 1, col: 1 }
}

///|
fn ParserState::peek(self : ParserState) -> Char? {
  if self.pos >= self.input.length() {
    None
  } else {
    self.input.get_char(self.pos)
  }
}

///|
fn ParserState::advance(self : ParserState) -> Unit {
  if self.pos < self.input.length() {
    let c : UInt16 = self.input[self.pos]
    if c == '\n' {
      self.line += 1
      self.col = 1
    } else {
      self.col += 1
    }
    self.pos += 1
  }
}

///|
fn ParserState::curr_pos(self : ParserState) -> Position {
  { line: self.line, col: self.col }
}

///|
fn ParserState::skip_whitespace(self : ParserState) -> Unit {
  while true {
    let c = self.peek()
    if c is Some(' ' | '\t') {
      self.advance()
    } else if c is Some('#') {
      self.skip_comment()
    } else {
      break
    }
  }
}

///|
fn ParserState::skip_whitespace_and_newlines(self : ParserState) -> Unit {
  while true {
    let c = self.peek()
    if c is Some(' ' | '\t' | '\n') {
      self.advance()
    } else if c is Some('#') {
      self.skip_comment()
    } else {
      break
    }
  }
}

///|
fn ParserState::skip_comment(self : ParserState) -> Unit {
  while true {
    let c = self.peek()
    if c is None || c is Some('\n') {
      break
    }
    self.advance()
  }
}

///|
fn ParserState::expect_newline_or_eof(self : ParserState) -> Unit raise ParseError {
  self.skip_whitespace()
  let c = self.peek()
  match c {
    None => ()
    Some('#') => {
      self.skip_comment()
      match self.peek() {
        None => ()
        Some('\n') => self.advance()
        Some(other) => raise SyntaxError(
          pos=self.curr_pos(),
          "expected newline after comment, got '\{other.to_string()}'",
        )
      }
    }
    Some('\n') => self.advance()
    Some(other) => raise SyntaxError(
      pos=self.curr_pos(),
      "expected newline, got '\{other.to_string()}'",
    )
  }
}

///|
/// Parse a bare key.
fn ParserState::parse_bare_key(self : ParserState) -> String? {
  let start = self.pos
  let mut ok = false
  while true {
    let c = self.peek()
